sysevent_script_action.script:
var bulk_proc_util = new MSSCustodyBulkProcessUtils_workspace();
gs.info('go to Call Maker Manual Bulk Task_WS');
var params = JSON.parse(event.parm1);
var sysparm_bulkid = params.sysparm_bulkid;
gs.info('sysparm_bulkid =' + sysparm_bulkid);

var sysparm_assignmentgroup = params.sysparm_assignmentgroup;
gs.info('sysparm_assignmentgroup =' + sysparm_assignmentgroup);

var sysparm_assignedto = params.sysparm_assignedto;
var sysparm_outcome = params.sysparm_outcome;
var sysparm_advice = params.sysparm_advice;
var sysparm_reasoncode = params.sysparm_reasoncode;
var sysparm_reasondescription = params.sysparm_reasondescription;
var sysparm_suspend = params.sysparm_suspend;
var sysparm_cancelby = params.sysparm_cancelby;
var sysparm_settlementtype = params.sysparm_settlementtype;
var sysparm_bktobk = params.sysparm_bktobk;
var sysparm_cancellationreference = params.sysparm_cancellationreference;
var sysparm_collectcancelcharge = params.sysparm_collectcancelcharge;
var sysparm_settDate = params.sysparm_settDate;
var sysparm_fxrTD = params.sysparm_fxrTD;
var sysparm_valDate = params.sysparm_valDate;
var sysparm_comments = params.sysparm_comments;
var sysparm_uploadType = params.sysparm_uploadType;
var sysparm_tasksCount = params.sysparm_tasksCount;
var sysparm_fxcx = params.sysparm_fxcx;
var sysparm_gdi = params = params.sysparm_gdi;
var sysparm_subOutcome = params.sysparm_subOutcome;
var sysparm_transRef = params.sysparm_transRef;
var sysparm_transType = params.sysparm_transType;
var sysparm_legStatus = params.sysparm_legStatus;
var sysparm_switchRef = params.sysparm_switchRef;
var sysparm_counterpartyCode = params.sysparm_counterpartyCode;

bulk_proc_util.updateMakerTask(sysparm_bulkid, sysparm_assignmentgroup, sysparm_assignedto, sysparm_outcome, sysparm_advice, sysparm_reasoncode, sysparm_reasondescription, sysparm_suspend, sysparm_cancelby, sysparm_settlementtype, sysparm_bktobk, sysparm_cancellationreference, sysparm_collectcancelcharge, sysparm_settDate, sysparm_fxrTD, sysparm_valDate, sysparm_comments, sysparm_uploadType, sysparm_tasksCount, sysparm_fxcx, sysparm_gdi, sysparm_subOutcome, sysparm_transRef, sysparm_transType, sysparm_legStatus, sysparm_switchRef, sysparm_counterpartyCode);
